private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {
    // Reject the insecure "none" algorithm unless the caller explicitly allows it.
    // In this implementation we consider "none" always disallowed.
    if ("none".equalsIgnoreCase(header.algorithm.getName())) {
        // A token with "none" must not contain a signature part.
        if (parts.length != 2) {
            throw new InvalidJWTSignatureException(
                "Token declares algorithm 'none' but contains a signature part");
        }
        // No verifier is required for unsigned tokens, so we skip verification.
    } else {
        // For all other algorithms a verifier must be supplied.
        if (verifier == null) {
            throw new MissingVerifierException(
                "No Verifier has been provided for verifying a signature signed using ["
                    + header.algorithm.getName() + "]");
        }
        // Signed tokens must contain exactly three parts.
        if (parts.length != 3) {
            throw new InvalidJWTSignatureException(
                "Signed token does not contain a signature part");
        }
    }

    // The message comprises the first two segments of the entire JWT,
    // the signature is the last segment (if present).
    int index = encodedJWT.lastIndexOf(".");
    byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

    // Perform signature verification only if an algorithm other than "none" is used.
    if (!"none".equalsIgnoreCase(header.algorithm.getName())) {
        byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
        verifier.verify(header.algorithm, message, signature);
    }

    JWT jwt = Mapper.deserialize(base64Decode(parts[1].getBytes(StandardCharsets.UTF_8)), JWT.class);

    // Verify expiration claim
    if (jwt.isExpired()) {
        throw new JWTExpiredException();
    }

    // Verify the notBefore claim
    if (jwt.isUnavailableForProcessing()) {
        throw new JWTUnavailableForProcessingException();
    }

    return jwt;
}
