public class DefaultURLConstructor implements URLConstructor {

    /* --------------------------------------------------------------------- */
    /*  Whitelist pattern – only alphanumerics, underscores, hyphens, dots   */
    /*  and forward slashes are allowed.  The pattern also ensures that the  */
    /*  path does not contain any empty segments (e.g. “//”) or traversal   */
    /*  sequences (“..”).                                                     */
    /* --------------------------------------------------------------------- */
    private static final Pattern SAFE_PATH_PATTERN =
            Pattern.compile("^/([A-Za-z0-9_.-]+(/)?)+$");

    /* --------------------------------------------------------------------- */
    /*  Returns the forward page name derived from the request path.         */
    /*  The method now validates the path against a strict whitelist and     */
    /*  normalises it to prevent directory traversal.                       */
    /* --------------------------------------------------------------------- */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // No path information – nothing to forward to
        if (pathInfo == null || pathInfo.isEmpty()) {
            return null;
        }

        // Reject any path that does not match the whitelist
        if (!SAFE_PATH_PATTERN.matcher(pathInfo).matches()) {
            return null;
        }

        // Normalise the path to collapse redundant separators and remove
        // any "." segments.  This step guarantees that the resulting path
        // is a clean, absolute path relative to the servlet context.
        String normalizedPath = java.nio.file.Paths.get(pathInfo)
                .normalize()
                .toString();

