    private final InputStream in;

    // other methods

    /**
     * Decompresses data from the given {@link InputStream} into the supplied output buffer.
     *
     * <p>The original implementation was vulnerable to denial‑of‑service attacks because it did
     * not validate the input stream.  Malformed data could cause an infinite loop or buffer
     * overrun.  The rewritten method performs comprehensive checks on every read operation,
     * validates packet sizes against the remaining space in the output buffer, and throws
     * {@link IOException} when the stream ends unexpectedly or the data is malformed.</p>
     *
     * @param in  the input stream containing compressed data
     * @param out the buffer to receive decompressed bytes
     * @throws IOException if the stream ends prematurely or the data is malformed
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading packet header");
            }

            // A packet size of zero is invalid in the Rgbe format.
            if (n == 0) {
                throw new IOException("Invalid packet size 0 encountered during decompression");
            }

            final int remaining = total - position;

            if (n > 128) { // Run‑length packet
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeated byte");
                }

                int count = n & 0x7F; // Equivalent to n - 128
                if (count > remaining) {
                    throw new IOException("Run‑length packet exceeds buffer capacity");
                }

                byte b = (byte) value;
                for (int i = 0; i < count; i++) {
                    out[position++] = b;
                }
            } else { // Literal packet
                int count = n;
                if (count > remaining) {
                    throw new IOException("Literal packet exceeds buffer capacity");
                }

                for (int i = 0; i < count; i++) {
                    int val = in.read();
                    if (val == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal bytes");
                    }
                    out[position++] = (byte) val;
                }
            }
        }
    }

    // other methods

    @Override
    public void close() throws IOException {
        in.close();
    }
}
