        enc.onMalformedInput(CodingErrorAction.REPLACE);

        final CharBuffer cb = CharBuffer.wrap(name);
        ByteBuffer out = ByteBuffer.allocate(
                estimateInitialBufferSize(enc, cb.remaining()));

        /* Track progress to guard against infinite loops caused by
         * repeatedly failing to consume input.  If the encoder fails to
         * advance the CharBuffer position for more than a small number
         * of attempts, we abort with an exception.
