public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /* --------------------------------------------------------------------- */
    /*  Locale validation utilities                                           */
    /* --------------------------------------------------------------------- */

    /**
     * A very permissive but safe regular expression that matches the most
     * common locale identifiers used by {@link LocalizedTextUtil}.  It accepts
     * language codes of 2–3 alphabetic characters optionally followed by an
     * underscore and a 2‑character country code.  Any other format will be
     * rejected to prevent injection of unexpected characters.
     */
