            Pattern.compile("^[a-zA-Z]{2,3}(_[a-zA-Z]{2})?$");

    /**
     * Validates that the supplied string conforms to {@link #LOCALE_PATTERN}.
     *
     * @param localeStr the locale string to validate
     * @return true if the string is a valid locale identifier, false otherwise
     */
    private boolean isValidLocale(String localeStr) {
        return localeStr != null && !localeStr.isEmpty() && LOCALE_PATTERN.matcher(localeStr).matches();
    }

    /* --------------------------------------------------------------------- */
    /*  Core interceptor logic                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@link Locale} or a {@code String}.  The method now
     * validates the string representation against a whitelist of accepted
     * locale formats to mitigate XSS and injection risks.
     *
     * @param requestedLocale the parameter from the request
     * @return the {@link Locale} or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;

        if (requestedLocale == null) {
            return null;
        }

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString();

            if (!isValidLocale(localeStr)) {
                LOG.warn("Rejected invalid locale request: '{}'", localeStr);
                return null;
            }

            locale = LocalizedTextUtil.localeFromString(localeStr, null);
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

