private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principal,
                                                Object credentials) throws NamingException {

    if (!(ldapContextFactory instanceof JndiLdapContextFactory)) {
        throw new IllegalArgumentException("Unsupported LdapContextFactory type");
    }
    JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;

    // Validate inputs
    if (principal == null || !(principal instanceof String) || ((String) principal).isEmpty()) {
        throw new IllegalArgumentException("Principal must be a non‑empty string");
    }
    if (credentials == null || !(credentials instanceof String) || ((String) credentials).isEmpty()) {
        throw new IllegalArgumentException("Credentials must be a non‑empty string");
    }

    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

    // Set authentication parameters *before* creating the context so that the bind
    // occurs over the negotiated TLS channel.
    env.put(Context.SECURITY_AUTHENTICATION,
            jndiLdapContextFactory.getAuthenticationMechanism());
    env.put(Context.SECURITY_PRINCIPAL, principal);
    env.put(Context.SECURITY_CREDENTIALS, credentials);

    LdapContext ctx = null;
    try {
        // Create the context – this performs the bind using the supplied credentials.
        ctx = new InitialLdapContext(env, null);

        // Negotiate STARTTLS after the bind to ensure the authentication
        // credentials are transmitted over a secure channel.
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();

        // Return the authenticated context
        return ctx;
    } catch (IOException e) {
        // TLS negotiation failed – close the context and surface a clear error.
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm(
                "Failed to negotiate TLS connection with '%s': %s",
                server(jndiLdapContextFactory),
                e.getMessage()));
        throw new CommunicationException("TLS negotiation failed: " + e.getMessage(), e);
    } catch (NamingException ne) {
        // Authentication or other naming error – close the context and rethrow.
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm(
                "LDAP authentication failed for '%s' on '%s': %s",
                principal,
                server(jndiLdapContextFactory),
                ne.getMessage()));
        throw ne;
    } catch (Throwable t) {
        // Unexpected failure – ensure cleanup and propagate.
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm(
                "Unexpected failure while establishing LDAP connection to '%s': %s",
                server(jndiLdapContextFactory),
                t.getMessage()));
        throw t;
    }
}
