private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    if (targetDirectory == null) throw new IllegalArgumentException("targetDirectory cannot be null");
    String targetDirCanonical = targetDirectory.getCanonicalPath();
    ArchiveEntry nextEntry = supplier.getNextReadableEntry();
    while (nextEntry != null) {
        String entryName = nextEntry.getName();
        if (entryName == null || entryName.isEmpty()) {
            nextEntry = supplier.getNextReadableEntry();
            continue;
        }
        // Reject absolute paths
        if (new File(entryName).isAbsolute()) {
            throw new IOException("absolute entry name not allowed: " + entryName);
        }
        // Reject path traversal components
        Path entryPath = Paths.get(entryName).normalize();
        for (int i = 0; i < entryPath.getNameCount(); i++) {
            if (entryPath.getName(i).toString().equals("..")) {
                throw new IOException("path traversal detected in entry name: " + entryName);
            }
        }
        File f = new File(targetDirectory, entryName);
        String canonical = f.getCanonicalPath();
        if (!canonical.startsWith(targetDirCanonical)) {
            throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
