public class Expander {

    // other methods

    /**
     * Safely extracts entries from the supplied archive into the target directory.
     *
     * @param supplier      provides the next readable entry from the archive
     * @param writer        writes the data of an entry to an {@link OutputStream}
     * @param targetDirectory the directory into which the archive contents are extracted
     * @throws IOException if an I/O error occurs or a security violation is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        if (targetDirectory == null) {
            throw new IllegalArgumentException("targetDirectory cannot be null");
        }

        // Resolve the canonical path of the target directory once
        final String targetDirCanonical = targetDirectory.getCanonicalPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            String entryName = nextEntry.getName();

            // Skip empty entry names
            if (entryName == null || entryName.isEmpty()) {
                nextEntry = supplier.getNextReadableEntry();
                continue;
            }

            /* ------------------------------------------------------------------
             * 1. Reject absolute paths – an entry name such as "/etc/passwd"
             *    would otherwise be written outside the target directory.
             * ------------------------------------------------------------------ */
            if (new File(entryName).isAbsolute()) {
                throw new IOException("absolute entry name not allowed: " + entryName);
            }

            /* ------------------------------------------------------------------
             * 2. Normalize the entry path and reject any component that is "..".
             *    This prevents path‑traversal attacks such as "../../secret.txt".
             * ------------------------------------------------------------------ */
            Path entryPath = Paths.get(entryName).normalize();
            for (int i = 0; i < entryPath.getNameCount(); i++) {
                if ("..".equals(entryPath.getName(i).toString())) {
                    throw new IOException("path traversal detected in entry name: " + entryName);
                }
            }

            /* ------------------------------------------------------------------
             * 3. Construct the destination file and verify that its canonical
             *    path remains within the target directory.  Using canonical paths
             *    ensures that symbolic links or other filesystem quirks cannot
             *    bypass the check.
             * ------------------------------------------------------------------ */
            File destFile = new File(targetDirectory, entryName);
            String destCanonical = destFile.getCanonicalPath();
            if (!destCanonical.startsWith(targetDirCanonical)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            /* ------------------------------------------------------------------
             * 4. Perform the actual extraction.
             * ------------------------------------------------------------------ */
            if (nextEntry.isDirectory()) {
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("failed to create directory " + destFile);
                }
