private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – they are cached in lastStoredEntry.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // populate lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Defensive checks for malformed ZIP entries.
    if (csize < 0) {
        throw new IOException("Negative entry size (" + csize + ") detected in ZIP entry " +
                               current.entry.getName());
    }

    // If we've already read the declared amount, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Ensure we do not read past the declared size.
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Refill the internal buffer if necessary.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // Stream ended before the declared size – treat as EOF.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;

        // Detect streams that report more data than the entry size.
        if (current.bytesReadFromStream > csize) {
            throw new IOException("Stream contains more data (" + current.bytesReadFromStream +
                                   ") than declared entry size (" + csize + ") for entry " +
                                   current.entry.getName());
        }
    }

    // Determine how many bytes to copy into the caller's buffer.
    int toRead = Math.min(buf.remaining(), length);
    if (remaining < toRead) {
        toRead = (int) remaining; // safe cast: remaining <= Integer.MAX_VALUE
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;

    // If we've just finished the entry, signal EOF on the next call.
    return toRead;
}
