import java.util.Calendar;
import static java.util.Calendar.*;

public final class CronTab {

    // other methods

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful. This addresses JENKINS-41864 and was added in 2.49
     */
    public Calendar ceil(Calendar cal) {
        // Create a clone of the input calendar to represent a date two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        // Set the future date limit to two years from the current calendar date.
        twoYearsFuture.add(Calendar.YEAR, 2);

        // Safety guard against infinite loops – limit the number of iterations.
        final int MAX_ITERATIONS = 1000;
        int iterations = 0;

        OUTER: while (true) {
            // Increment iteration counter and enforce the limit.
            if (++iterations > MAX_ITERATIONS) {
                throw new IllegalStateException(
                        "Exceeded maximum iterations while computing ceil for CronTab");
            }

            // If the date exceeds the two‑year future limit, it is considered too rare or impossible.
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // Iterate over each CalendarField in the predefined adjustment order to modify the calendar date.
            for (CalendarField f : CalendarField.ADJUST_ORDER) {
                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // No adjustment needed for this field.
                if (cur == next) {
                    continue;
                }

                // Clear all lower fields if the current field value changes.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // Handle cases where the next value is invalid (negative).
                if (next < 0) {
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    continue OUTER;
                } else {
                    // Set the calendar field to the next valid value.
                    f.setTo(cal, next);

                    // Restart the adjustment process if the field requires re‑evaluation after modification.
                    if (f.redoAdjustmentIfModified) {
                        continue OUTER;
                    }
                }
            }

            // All fields are valid and no further adjustments are needed.
            return cal;
        }
    }

    // other methods

}
