    /**
     * Creates a {@link DocumentBuilderFactory} configured to mitigate XXE attacks.
     *
     * @return a secure {@link DocumentBuilderFactory}
     */
    private static DocumentBuilderFactory newSecureDocumentBuilderFactory() {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        try {
            // Disable DTDs entirely
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external entities
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // Disable XInclude
            dbf.setXIncludeAware(false);
            // Do not expand entity references
            dbf.setExpandEntityReferences(false);
            // Enable secure processing
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (Exception e) {
            // If any feature is unsupported, fall back to default but log the issue
            // Logging omitted for brevity; in production, use a logger
        }
        return dbf;
    }

    /**
     * Parses XML from a {@link String} into a {@link Document} using a secure parser.
     */
    private static Document parseSecure(String xml) throws Exception {
        DocumentBuilderFactory dbf = newSecureDocumentBuilderFactory();
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(new InputSource(new StringReader(xml)));
    }

    /**
     * Parses XML from an {@link InputStream} into a {@link Document} using a secure parser.
     */
    private static Document parseSecure(InputStream is) throws Exception {
        DocumentBuilderFactory dbf = newSecureDocumentBuilderFactory();
        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(is);
    }

